import subprocess
def run(args, inp=None):
    return subprocess.run(["./executable"]+args, input=inp, capture_output=True, text=True)
def body(s):
    idx=s.find("</defs>")
    return s[idx+len("</defs>"):].strip() if idx!=-1 else s
def via_stdin(txt):
    r=run([], inp=txt)
    return r
for txt in ["", "a", "ab", "a\nb\n", "a\nbb\nccc\n", "\n", "\n\n", " \n", "aa\n", "aa\nbb\n"]:
    r=via_stdin(txt)
    first=r.stdout.splitlines()[0] if r.stdout else ""
    print(repr(txt), first, "|", body(r.stdout).replace("\n","\\n"))
PY"}

