import sys; sys.path.insert(0,'/tmp')
from probe import *
import subprocess, re
def order(txt):
    r=run([],inp=txt); b=body(r.stdout); elems=[]
    for l in b.splitlines():
        l=l.strip()
        m=re.search(r'>([^<]*)</text>',l)
        if m: elems.append(m.group(1))
    return elems
def make(pos):
    maxx=max(x for x,y in pos); maxy=max(y for x,y in pos)
    rows=[[" "]*(maxx+1) for _ in range(maxy+1)]
    for (x,y),c in pos.items(): rows[y][x]=c
    return "\n".join("".join(r).rstrip() for r in rows)
for dx in range(0,5):
    for dy in range(1,4):
        txt=make({(0,0):'a',(dx,dy):'b',(10,0):'c'})
        print(f"dx={dx} dy={dy}", order(txt), repr(txt))
