import itertools
pts=[(24,8),(16,8),(10,12),(8,16),(8,32),(4,24),(24,4)]
# circle through 3 points function
def circle(p1,p2,p3):
    import sympy as sp
    x,y=sp.symbols('x y')
    sol=sp.solve([(x-p1[0])**2+(y-p1[1])**2-(x-p2[0])**2-(y-p2[1])**2,(x-p1[0])**2+(y-p1[1])**2-(x-p3[0])**2-(y-p3[1])**2],[x,y])
    return sol
for combo in itertools.combinations(pts,3):
    try:
        s=circle(*combo)
        cx,cy=float(s[0][0]) if isinstance(s,list) else float(s[x]),0
    except Exception as e:
        pass
PY"}

