        cand,conf=best_subcommand(tok)
        msg=f"error: The subcommand '{tok}' wasn't recognized\n"
        usage=used_smart()
        if conf>0.8:
            msg+=f"\tDid you mean '{cand}'?\n\nIf you believe you received this message in error, try re-running with '{bin_name} -- {tok}'\n"
        msg+=f"\nUSAGE:\n    {usage}\n\nFor more information try --help\n"
        eprint(msg); sys.exit(1)

    # Build subcommand parser (nested function using closure for errors)
    def parse_build(rest):
        # rest tokens after 'build'
        b_used=[]
        b_values={}
        b_counts={}
        b_pending=None
        b_after=False
        j=0
        def b_smart(suggested_key=None):
            keys=set(b_used)
            if suggested_key: keys.add(suggested_key)
            parts=[]
            for k in ['input','outdir']:
                if k in keys:
                    parts.append(f"--{k} <{k}>")
            if not parts:
                return f"{bin_name} build [OPTIONS]"
