class Prim:
    __slots__=('kind','p1','p2','r','sweep','large','cls','points','x','y','w','h','rx','text','seq','cluster','cell','nodes')
    def __init__(self, kind, seq=0, cluster=0, cell=None):
        self.kind=kind; self.seq=seq; self.cluster=cluster; self.cell=cell
        self.p1=None; self.p2=None; self.r=0; self.sweep=0; self.large=0; self.cls=''
        self.points=None; self.x=0; self.y=0; self.w=0; self.h=0; self.rx=0; self.text=''; self.nodes=None

def rust_lines(text):
    if text == "":
        return []
    parts = text.split('\n')
    if text.endswith('\n'):
        parts.pop()
    out=[]
    for p in parts:
        if p.endswith('\r'):
            p=p[:-1]
        out.append(p)
    return out

def extract_quotes(lines):
    quoted=[]  # (x,y,string)
    new_lines=[]
    for y,line in enumerate(lines):
        chars=list(line)
        n=len(chars)
        to_blank=[]
        i=0; escaped=False; open_idx=None; esc_in=False
        pairs=[]
        while i<n:
            c=chars[i]
            if open_idx is not None:
                if esc_in:
                    esc_in=False
                elif c=='\\':
                    esc_in=True
                elif c=='"':
                    pairs.append((open_idx,i))
                    open_idx=None
                i+=1; continue
            else:
                if escaped:
                    escaped=False
                elif c=='\\':
                    escaped=True
                elif c=='"':
                    open_idx=i; esc_in=False
                i+=1; continue
        for a,b in pairs:
            content=''.join(chars[a+1:b])
            quoted.append((a,y,content))
            for k in range(a,b+1):
                chars[k]=' '
        new_lines.append(''.join(chars))
    return new_lines, quoted

def convert(text, settings):
    lines = rust_lines(text)
    lines, quoted = extract_quotes(lines)
    # grid
    cells={}
    for y,line in enumerate(lines):
        for x,ch in enumerate(line):
            if not is_ws(ch):
                cells[(x,y)]=ch
    if cells:
        maxx=max(x for x,y in cells); maxy=max(y for x,y in cells)
    else:
        maxx=0; maxy=0
    total_w = (maxx+2)*8
    total_h = (maxy+2)*16

    def ch_at(x,y):
        return cells.get((x,y))
    def is_hline_char(c):
        return c in H_LINE_CHARS or c in ('┌','┐','└','┘','├','┤','┬','┴','┼','╭','╮','╯','╰','═','╔','╗','╚','╝','╠','╣','╦','╩','╬','╒','╓','╕','╖','╘','╙','╛','╜','╞','╡','╤','╧','╪')
    def is_vline_char(c):
        return c in V_LINE_CHARS or c in ('┌','┐','└','┘','├','┤','┬','┴','┼','╭','╮','╯','╰','║','╔','╗','╚','╝','╠','╣','╦','╩','╬','╓','╖','╙','╜','╟','╢','╥','╨','╫')
    # clusters: 8-neighbor
    visited=set(); clusters=[]
    cell_cluster={}
    for cell in sorted(cells.keys(), key=lambda p:(p[1],p[0])):
        if cell in visited: continue
        comp=[]; stack=[cell]; visited.add(cell)
        while stack:
            cur=stack.pop(); comp.append(cur)
            cx,cy=cur
            for dx in (-1,0,1):
                for dy in (-1,0,1):
                    if dx==0 and dy==0: continue
                    nb=(cx+dx,cy+dy)
                    if nb in cells and nb not in visited:
                        visited.add(nb); stack.append(nb)
        cid=len(clusters); clusters.append(comp)
        for c in comp: cell_cluster[c]=cid

    seq_counter=[0]
    def next_seq():
        s=seq_counter[0]; seq_counter[0]+=1; return s

    # classification
    H_CONN = set('-~─┄+') | set('┌┐└┘├┤┬┴┼╭╮╯╰') | set(".'`,*#oO●○")
    V_CONN = set('|│┆┊╎+:') | set('┌┐└┘├┤┬┴┼') | set("*#oO●○")
    def horiz_conn(c):
        return c in H_CONN or is_hline_char(c)
    def vert_conn(c):
        return c in V_CONN or is_vline_char(c)

    def classify(x,y):
        c=cells[(x,y)]
        # unicode explicit
        if c in UNICODE_FRAGS:
            return 'graphic'
        if c in '-|/\\_~=':
            return 'graphic'
        if c in '─│┄┆┊╎═║':
            return 'graphic'
        if c=='(' or c==')':
            return 'graphic'
        if c==':':
            if ch_at(x,y-1)==':' or ch_at(x,y+1)==':':
                return 'graphic'
            return 'text'
        if c=='#':
            # graphic if any cardinal neighbor is line-ish or #
            for nb in [ch_at(x-1,y),ch_at(x+1,y),ch_at(x,y-1),ch_at(x,y+1)]:
                if nb is not None and (nb in '-|/\\_~=+:#' or is_hline_char(nb) or is_vline_char(nb) or nb in UNICODE_FRAGS):
                    return 'graphic'
            return 'text'
        if c in MARKER_CHARS:
            # graphic if cardinal neighbor is a line char
            checks=[(ch_at(x-1,y), 'h'),(ch_at(x+1,y),'h'),(ch_at(x,y-1),'v'),(ch_at(x,y+1),'v')]
            for nb,dir_ in checks:
                if nb is None: continue
                if dir_=='h' and (nb in '-~─┄+/\\|' or is_hline_char(nb)):
                    return 'graphic'
                if dir_=='v' and (nb in '|│┆┊╎+/\\-' or is_vline_char(nb)):
                    return 'graphic'
            return 'text'
        if c=='+':
            if horiz_conn(ch_at(x-1,y)) or horiz_conn(ch_at(x+1,y)) or vert_conn(ch_at(x,y-1)) or vert_conn(ch_at(x,y+1)):
                # check direction-specific: horiz neighbor must be horiz-conn, vert neighbor vert-conn
                if (ch_at(x-1,y) is not None and horiz_conn(ch_at(x-1,y))) or (ch_at(x+1,y) is not None and horiz_conn(ch_at(x+1,y))) or (ch_at(x,y-1) is not None and vert_conn(ch_at(x,y-1))) or (ch_at(x,y+1) is not None and vert_conn(ch_at(x,y+1))):
                    return 'graphic'
            return 'text'
        if c=='.':
            horiz = (ch_at(x-1,y) in H_LINE_CHARS) or (ch_at(x+1,y) in H_LINE_CHARS)
            if not horiz: return 'text'
            # south vertical same or diagonal, or south slash/paren diagonal
            s = ch_at(x,y+1); sw=ch_at(x-1,y+1); se=ch_at(x+1,y+1)
            if (s is not None and is_vline_char(s)) or (sw is not None and is_vline_char(sw)) or (se is not None and is_vline_char(se)) or sw in ('/','(') or se in ('\\',')'):
                return 'graphic'
            return 'text'
        if c==',':
            if ch_at(x+1,y) in H_LINE_CHARS and (ch_at(x,y+1) is not None and is_vline_char(ch_at(x,y+1))):
                return 'graphic'
            return 'text'
        if c=="'":
            horiz = (ch_at(x-1,y) in H_LINE_CHARS) or (ch_at(x+1,y) in H_LINE_CHARS)
            if not horiz: return 'text'
            n_ = ch_at(x,y-1); nw=ch_at(x-1,y-1); ne=ch_at(x+1,y-1)
            if (n_ is not None and is_vline_char(n_)) or (nw is not None and is_vline_char(nw)) or (ne is not None and is_vline_char(ne)):
                return 'graphic'
            return 'text'
        if c=='`':
            if ch_at(x+1,y) in H_LINE_CHARS and ((ch_at(x,y-1) is not None and is_vline_char(ch_at(x,y-1))) or (ch_at(x-1,y-1) is not None and is_vline_char(ch_at(x-1,y-1)))):
                return 'graphic'
            return 'text'
        if c in '<>':
            if c=='>':
                if ch_at(x-1,y) in ('-','~','─','┄','+','>'):
                    return 'graphic'
                if ch_at(x+1,y) in ('-','~','─','┄','+'):
                    return 'graphic'
            else:
                if ch_at(x+1,y) in ('-','~','─','┄','+','<'):
                    return 'graphic'
                if ch_at(x-1,y) in ('-','~','─','┄','+'):
                    return 'graphic'
            return 'text'
        if c in '^v':
            if c=='^':
                if ch_at(x,y+1) is not None and vert_conn(ch_at(x,y+1)):
                    return 'graphic'
                if ch_at(x,y-1) is not None and vert_conn(ch_at(x,y-1)):
                    return 'graphic'
            else:
                if ch_at(x,y-1) is not None and vert_conn(ch_at(x,y-1)):
                    return 'graphic'
                if ch_at(x,y+1) is not None and vert_conn(ch_at(x,y+1)):
                    return 'graphic'
            return 'text'
        return 'text'

    kind={}
    for cell in cells:
        kind[cell]=classify(*cell)

    prims=[]  # all primitives per cluster processing later
    markers=[]  # dict info
    # helper to add prim
    def add(p, cell):
        p.seq=next_seq(); p.cluster=cell_cluster[cell]; p.cell=cell; prims.append(p); return p
    def line_prim(x1,y1,x2,y2,cls,cell):
        p=Prim('line',cell=cell); p.p1=(x1,y1); p.p2=(x2,y2); p.cls=cls; return add(p,cell)
    def arc_prim(x1,y1,r,sweep,x2,y2,cell,cls='nofill'):
        p=Prim('arc',cell=cell); p.p1=(x1,y1); p.p2=(x2,y2); p.r=r; p.sweep=sweep; p.cls=cls; return add(p,cell)
    def circle_prim(cx,cy,r,cls,cell):
        p=Prim('circle',cell=cell); p.x=cx; p.y=cy; p.r=r; p.cls=cls; return add(p,cell)
    def rect_prim(x,y,w,h,cls,rx,cell):
        p=Prim('rect',cell=cell); p.x=x; p.y=y; p.w=w; p.h=h; p.cls=cls; p.rx=rx; return add(p,cell)
    def poly_prim(points,cls,cell):
        p=Prim('polygon',cell=cell); p.points=points; p.cls=cls; return add(p,cell)

    # Text runs per cluster/row
    consumed=set()
    # process cells in row-major for fragment generation
    sorted_cells=sorted(cells.keys(), key=lambda p:(p[1],p[0]))
    # First handle text runs: mark text cells; runs will be generated in loop below

    for (x,y) in sorted_cells:
        if kind[(x,y)]!='graphic':
            continue
        c=cells[(x,y)]
        X=x*8; Y=y*16; cx=X+4; cy=Y+8
        cell=(x,y)
        # unicode frags
        if c in UNICODE_FRAGS:
            # marker unicode circles: if ○/● adjacent to line, treat as marker instead
            if c in ('○','●'):
                markers.append({'cell':cell,'char':c,'cx':cx,'cy':cy,'type':MARKER_CHARS[c]})
                continue
            for fr in UNICODE_FRAGS[c]:
                if fr[0]=='line':
                    _,x1,y1,x2,y2,cls=fr; line_prim(X+x1,Y+y1,X+x2,Y+y2,cls,cell)
                elif fr[0]=='arc':
                    _,x1,y1,r,sw,x2,y2,cls=fr; arc_prim(X+x1,Y+y1,r,sw,X+x2,Y+y2,cell,cls)
                elif fr[0]=='circle':
                    _,ccx,ccy,r,cls=fr; circle_prim(X+ccx,Y+ccy,r,cls,cell)
                elif fr[0]=='rect':
                    _,rx_,ry,rw,rh,cls,rxv=fr; rect_prim(X+rx_,Y+ry,rw,rh,cls,rxv,cell)
                elif fr[0]=='polygon':
                    _,pts,cls=fr; poly_prim([(X+px,Y+py) for px,py in pts],cls,cell)
            continue
        if c=='-':
            x1=X; x2=X+8
            w=ch_at(x-1,y); e=ch_at(x+1,y)
            if w in ('|','│','/','\\','╱','╲'): x1=cx-8  # west neighbor centre: (x-1)*8+4 = X-4
            # correction: west neighbor centre = X-4
            if w in ('|','│','/','\\','╱','╲'): x1=X-4
            if e in ('|','│','/','\\','╱','╲'): x2=X+12
            line_prim(x1,cy,x2,cy,'solid',cell)
            continue
        if c=='~':
            x1=X; x2=X+8
            w=ch_at(x-1,y); e=ch_at(x+1,y)
            if w in ('|','│','/','\\','╱','╲'): x1=X-4
            if e in ('|','│','/','\\','╱','╲'): x2=X+12
            line_prim(x1,cy,x2,cy,'broken',cell)
            continue
        if c=='─':
            line_prim(X,cy,X+8,cy,'solid',cell); continue
        if c=='┄':
            line_prim(X,cy,X+8,cy,'broken',cell); continue
        if c=='=':
            line_prim(X,cy-2,X+8,cy-2,'solid',cell); line_prim(X,cy+2,X+8,cy+2,'solid',cell); continue
        if c=='_':
            line_prim(X,Y+16,X+8,Y+16,'solid',cell); continue
        if c=='|':
            y1=Y; y2=Y+16
            n_=ch_at(x,y-1); s_=ch_at(x,y+1)
            if n_ in ('/','\\','╱','╲'): y1=Y-8
            if n_ in MARKER_CHARS or n_=='#': pass # handled by node connector / stub
            if s_ in ('^',): y2=Y+16+4  # will be adjusted? Actually | above ^? south neighbor is ^ polygon: extend to its centre-4: (y+1)*16+8-4 = Y+20
            if s_=='^': y2=Y+20
            # if south neighbor is marker/node, extend end to centre-4
            if s_ in MARKER_CHARS or s_=='#': y2=Y+20  # centre of below cell = Y+24, -4 = Y+20 ; wait below cell centre = (y+1)*16+8=Y+24, -4=Y+20 correct
            line_prim(cx,y1,cx,y2,'solid',cell); continue
        if c in ('│','┆','┊','╎'):
            cls='broken' if c!='│' else 'solid'
            line_prim(cx,Y,cx,Y+16,cls,cell); continue
        if c==':':
            line_prim(cx,Y,cx,Y+16,'broken',cell); continue
        if c=='/' or c=='╱':
            s_=ch_at(x,y+1)
            # diagonal continuation SW/NE
            cont = (ch_at(x-1,y+1)=='/' or ch_at(x+1,y-1)=='/')
            if s_ is not None and is_vline_char(s_) and not cont:
                line_prim(X+8,Y,cx,cy,'solid',cell)
            else:
                line_prim(X+8,Y,X,Y+16,'solid',cell)
            continue
        if c=='\\' or c=='╲':
            s_=ch_at(x,y+1)
            cont = (ch_at(x-1,y-1)=='\\' or ch_at(x+1,y+1)=='\\')
            if s_ is not None and is_vline_char(s_) and not cont:
                line_prim(X,Y,cx,cy,'solid',cell)
            else:
                line_prim(X,Y,X+8,Y+16,'solid',cell)
            continue
        if c=='(':
            if ch_at(x+1,y)==')':
                circle_prim(X+8,cy,4,'nofill',cell)
            else:
                arc_prim(X+8,Y,16,0,X+8,Y+16,cell)
            continue
        if c==')':
            if ch_at(x-1,y)=='(':
                continue
            arc_prim(X,Y,16,1,X,Y+16,cell); continue
        if c=='#':
            rect_prim(X,cy-4,8,8,'solid filled',0,cell)
            continue
        if c in MARKER_CHARS:
