def jaro(s1,s2):
    if s1==s2: return 1.0
    len1,len2=len(s1),len(s2)
    if len1==0 or len2==0: return 0.0
    match_distance=max(len1,len2)//2-1
    if match_distance<0: match_distance=0
    s1_matches=[False]*len1; s2_matches=[False]*len2
    matches=0
    for i in range(len1):
        start=max(0,i-match_distance); end=min(i+match_distance+1,len2)
        for j in range(start,end):
            if s2_matches[j]: continue
            if s1[i]!=s2[j]: continue
            s1_matches[i]=True; s2_matches[j]=True; matches+=1; break
    if matches==0: return 0.0
    t=0; k=0
    for i in range(len1):
        if not s1_matches[i]: continue
        while not s2_matches[k]: k+=1
        if s1[i]!=s2[k]: t+=1
        k+=1
    t//=2
    return (matches/len1 + matches/len2 + (matches-t)/matches)/3

def jaro_winkler(s1,s2):
    j=jaro(s1,s2)
    prefix=0
    for i in range(min(len(s1),len(s2),4)):
        if s1[i]==s2[i]: prefix+=1
        else: break
    return j + prefix*0.1*(1-j)

def best_subcommand(tok):
    best=None; bestv=0
    for cand in ['build','help']:
        v=jaro_winkler(tok,cand)
        if v>bestv:
            bestv=v; best=cand
    return best,bestv

ARG_DEFS = [
    # key, long, value_name, short
    ('background','background','background',None),
    ('fill-color','fill-color','fill-color',None),
    ('font-family','font-family','font-family',None),
    ('font-size','font-size','font-size',None),
    ('s','s',None,'s'),
    ('output','output','output','o'),
    ('scale','scale','scale',None),
    ('stroke-color','stroke-color','stroke-color',None),
    ('stroke-width','stroke-width','stroke-width',None),
]
ARG_ORDER=[a[0] for a in ARG_DEFS]
LONG_MAP={a[1]:a for a in ARG_DEFS}
SHORT_MAP={a[3]:a for a in ARG_DEFS if a[3]}

def smart_usage(bin_name, used, suggested_key=None):
    keys=set(used)
    if suggested_key: keys.add(suggested_key)
    # order by ARG_ORDER
    parts=[]
    for k in ARG_ORDER:
        if k in keys:
            if k=='s':
                parts.append('-s')
            else:
                d=LONG_MAP[[a[1] for a in ARG_DEFS if a[0]==k][0]]
                parts.append(f"--{d[1]} <{d[2]}>")
    if not parts:
        return f"{bin_name} [FLAGS] [OPTIONS] [input] [SUBCOMMAND]"
    return f"{bin_name} " + " ".join(parts)

def eprint(s):
    sys.stderr.write(s)

def panic(location, msg):
    pid=os.getpid()
    bt=os.environ.get('RUST_BACKTRACE','')
    if bt and bt!='0':
        if bt=='full':
            # approximate: original prints addresses; we cannot match, print similar header
            eprint(f"\nthread 'main' ({pid}) panicked at {location}:\n{msg}\nstack backtrace:\nnote: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.\n")
        else:
            eprint(f"\nthread 'main' ({pid}) panicked at {location}:\n{msg}\nstack backtrace:\nnote: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.\n")
    else:
        eprint(f"\nthread 'main' ({pid}) panicked at {location}:\n{msg}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.exit(101)

def os_error_str(e):
    # e is OSError
    return f"{e.strerror} (os error {e.errno})"

def parse_rust_u64(s, argname):
    if s=='':
        eprint(f"Illegal value for argument {argname}: cannot parse integer from empty string\n"); sys.exit(1)
    # Rust: optional + then digits
    t=s[1:] if s.startswith('+') else s
    if t=='' or not all('0'<=ch<='9' for ch in t):
        eprint(f"Illegal value for argument {argname}: invalid digit found in string\n"); sys.exit(1)
    v=int(t)
    if v>18446744073709551615:
        eprint(f"Illegal value for argument {argname}: number too large to fit in target type\n"); sys.exit(1)
    return v

def parse_rust_f32(s, argname):
    if s=='':
        eprint(f"Illegal value for argument {argname}: cannot parse float from empty string\n"); sys.exit(1)
    # validate Rust float syntax: use regex
    # Rust accepts: inf, -inf, infinity?, NaN case variations? and decimal forms
    low=s.lower()
    if low in ('inf','+inf','-inf','infinity','+infinity','-infinity','nan','+nan','-nan'):
        return f32(float(s.replace('infinity','inf')) if 'infinity' in low else float(s))
    if not re.fullmatch(r'[+-]?((\d+(\.\d*)?)|(\.\d+))([eE][+-]?\d+)?', s):
        eprint(f"Illegal value for argument {argname}: invalid float literal\n"); sys.exit(1)
    return f32(float(s))

def do_build(args, bin_name):
    # returns exit code 1 always (except help/version/clap errors handled in parser)
    # args: dict input/outdir values or None
    inp=args.get('input')
    outdir=args.get('outdir')
    if inp is None:
        inp_pattern = "*.bob"  # inferred default giving empty dir error
        # Actually original without -i gives dir empty error; pattern unknown but effect same
        # Use a pattern that yields empty dir
        inp_pattern = ""
        # But empty pattern case in original without -i did NOT panic, it gave error. So treat missing as special:
        sys.stdout.write("[Error]: No such dir name is  !\n")
        return 1
    pattern=inp
    if pattern=="":
        panic("crates/svgbob_cli/src/main.rs:195:29", "called `Option::unwrap()` on a `None` value")
    # split dir and filename part at last '/'
    if '/' in pattern:
        dir_name, file_pat = pattern.rsplit('/',1)
        # For patterns like "sub//*.bob", dir_name is "sub/" -> normalize display? Original prints paths as dir/file
        # Keep dir_name as is for path construction but display uses Path-like join.
        dir_for_exists = dir_name if dir_name!='' else '/'
        display_dir = dir_name
    else:
        dir_name=''; file_pat=pattern; display_dir=''; dir_for_exists=''
    # extension extraction: after last '.' in file_pat, if no dot -> "bob"
    if '.' in file_pat:
        ext=file_pat.rsplit('.',1)[1]
    else:
        ext='bob'
    # check dir exists
    check_dir = dir_name if dir_name!='' else '.'
    # Original: if pattern has no '/', dir is '' and error shows empty. That occurs even if current dir exists.
    if '/' not in pattern:
        sys.stdout.write("[Error]: No such dir name is  !\n"); return 1
    if not os.path.isdir(dir_for_exists):
        sys.stdout.write(f"[Error]: No such dir name is {dir_name} !\n"); return 1
    # outdir creation
    if outdir is not None:
        try:
            os.makedirs(outdir, exist_ok=True)
            # But if outdir is existing file, makedirs raises FileExists; original prints "File exists (os error 17)"
            if not os.path.isdir(outdir):
                raise FileExistsError(17, "File exists")
        except FileExistsError:
            sys.stdout.write("File exists (os error 17)\n"); return 1
        except OSError as e:
            sys.stdout.write(f"{e.strerror} (os error {e.errno})\n"); return 1
    # list entries in dir (non-recursive) in OS order
    try:
        entries=list(os.scandir(dir_for_exists))
    except OSError as e:
        sys.stdout.write(f"[Error]: No such dir name is {dir_name} !\n"); return 1
    for entry in entries:
        if not entry.is_file():
            continue
        name=entry.name
        # filter by extension: name ends with '.'+ext ; also (?) file_pat '*' etc already accounted via ext
        # For pattern "*.*", ext='*' -> no match
        if '.' not in name:
            continue
        file_ext=name.rsplit('.',1)[1]
        if file_ext!=ext:
            continue
        src_path = f"{display_dir}/{name}" if display_dir else name
        # Destination
        stem=name[:-(len(ext)+1)] if name.endswith('.'+ext) else name
        dest_name=stem+".svg"
        if outdir is not None:
            dest_path=f"{outdir}/{dest_name}"
        else:
            dest_path=f"{display_dir}/{dest_name}" if display_dir else dest_name
        # Original prints before reading/conversion (panics after print for invalid utf8)
        sys.stdout.write(f"{src_path} => {dest_path}\n"); sys.stdout.flush()
        # read file
        try:
            with open(entry.path,'rb') as fh:
                data=fh.read()
        except OSError as e:
            panic("crates/svgbob_cli/src/main.rs:246:32", f"called `Result::unwrap()` on an `Err` value: Os {{ code: {e.errno}, kind: { 'IsADirectory' if e.errno==21 else 'Other'}, message: \"{e.strerror}\" }}")
        try:
            text=data.decode('utf-8')
        except UnicodeDecodeError:
            panic("crates/svgbob_cli/src/main.rs:246:32", "called `Result::unwrap()` on an `Err` value: Error { kind: InvalidData, message: \"stream did not contain valid UTF-8\" }")
        svg=convert(text, Settings())
        # write dest
        try:
            with open(dest_path,'w',encoding='utf-8',newline='\n') as out:
                out.write(svg)
        except OSError as e:
            # What does original do on write error in build? unknown; print?
            sys.stdout.write(f"{e.strerror} (os error {e.errno})\n"); return 1
    return 1

def main(argv):
    bin_name=os.path.basename(argv[0]) if argv else "executable"
    args=argv[1:]

    # Parser state
    used=[]  # arg keys in order encountered
    values={}  # key -> value (for options)
    counts={}
    input_val=None
    inline=False
    pending_missing=None  # arg def of option missing value
    after_dd=False
    i=0
    # For help subcommand handling, we need lookahead: tokens that are 'help'/'build' as bare words trigger subcommands
    def used_smart(suggested=None):
        return smart_usage(bin_name, used, suggested)
    def err_unknown(tok_display, suggested_key=None, suggested_display=None):
