#!/usr/bin/env python3
import sys, os, re, math, struct, unicodedata

# ---------- Rust f32 formatting ----------
def f32(x):
    try:
        return struct.unpack('f', struct.pack('f', float(x)))[0]
    except OverflowError:
        return math.inf if x>0 else -math.inf

def fmt_f32(v):
    v = f32(v)
    if math.isnan(v):
        return "NaN"
    if math.isinf(v):
        return "inf" if v>0 else "-inf"
    if v == 0.0:
        return "-0" if math.copysign(1.0, v) < 0 else "0"
    # shortest precision that round-trips
    s = None
    for prec in range(1, 11):
        cand = format(v, f'.{prec-1}e')  # scientific with prec sig digits
        if f32(float(cand)) == v:
            s = cand
            break
    if s is None:
        s = format(v, '.9e')
    # parse mantissa/exponent
    mant, exp = s.split('e')
    exp = int(exp)
    mant = mant.replace('-','').replace('.','')
    digits = mant.rstrip('0') or '0'
    # Actually for cases like 1e+02 digits after rstrip: "1" ok. But if shortest was e.g. 1.20? won't happen due prec loop.
    # Recompute digits without stripping needed precision? format with prec gives trailing zeros; rstrip is okay because those were not needed? 
    # But if prec minimal, trailing zero could be significant for roundtrip? e.g. 1.0 -> digits "1"
    sign = '-' if v < 0 else ''
    point = exp + 1
    if point <= 0:
        return sign + "0." + "0"*(-point) + digits
    elif point >= len(digits):
        return sign + digits + "0"*(point-len(digits))
    else:
        return sign + digits[:point] + "." + digits[point:]

def fmt_num(v):
    # coordinates are f32-ish values in unscaled space; after scaling they become f32
    return fmt_f32(v)

