def is_ws(c):
    if c in '\t\n\x0b\x0c\r ':
        return True
    if c in '\u0085\u2028\u2029':
        return True
    return unicodedata.category(c) == 'Zs'

def xml_escape(s):
    return (s.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
             .replace('"','&quot;').replace("'",'&#39;'))

