                            # Use xs/ys if vert lines extend beyond horiz in y, or horiz extend beyond in x? Check |---| : vert extends, horiz are within. bbox = (xs[0], miny, w=xs diff, h=maxy-miny) which matches.
                            # If horiz extends beyond, bbox x would be horiz extents and y = ys. That likely also matches bbox concept.
                            rp=Prim('rect',cell=comp[0].cell); rp.x=rx0; rp.y=ry0; rp.w=rw; rp.h=rh; rp.cls='solid nofill'; rp.rx=0; rp.seq=min(p.seq for p in comp); rp.cluster=cid
                            rects_new.append(rp)
                            for p in comp: consumed.add(id(p))
                            continue
            if len(comp)==8:
                comp_lines=[p for p in comp if p.kind=='line']
                comp_arcs=[p for p in comp if p.kind=='arc']
                if len(comp_lines)==4 and len(comp_arcs)==4:
                    horiz=[p for p in comp_lines if p.p1[1]==p.p2[1]]
                    vert=[p for p in comp_lines if p.p1[0]==p.p2[0]]
                    radii=set(p.r for p in comp_arcs)
                    if len(horiz)==2 and len(vert)==2 and len(radii)==1:
                        ys=sorted(set(p.p1[1] for p in horiz)); xs=sorted(set(p.p1[0] for p in vert))
                        if len(ys)==2 and len(xs)==2:
                            rp=Prim('rect',cell=comp[0].cell); rp.x=xs[0]; rp.y=ys[0]; rp.w=xs[1]-xs[0]; rp.h=ys[1]-ys[0]; rp.cls='solid nofill'; rp.rx=list(radii)[0]; rp.seq=min(p.seq for p in comp); rp.cluster=cid
                            rects_new.append(rp)
                            for p in comp: consumed.add(id(p))
                            continue
            # circle from 2 arcs () handled at generation; also check 2 arcs sharing both endpoints with ()? already
        lines=[p for p in lines if id(p) not in consumed]
        arcs=[p for p in arcs if id(p) not in consumed]
        others.extend(rects_new)

        # --- Grouping lines+arcs into groups by connectivity (endpoint sharing / endpoint on segment) ---
        la2=lines+arcs
        # components again
        parent2=list(range(len(la2)))
        def find2(a):
            while parent2[a]!=a:
                parent2[a]=parent2[parent2[a]]; a=parent2[a]
            return a
        def union2(a,b):
            ra,rb=find2(a),find2(b)
            if ra!=rb: parent2[rb]=ra
        for i in range(len(la2)):
            for j in range(i+1,len(la2)):
                A=la2[i]; B=la2[j]
                share=False
                for pa in (A.p1,A.p2):
                    for pb in (B.p1,B.p2):
                        if pa==pb: share=True
                if not share and A.kind=='line' and B.kind=='line':
                    if point_on_segment(A.p1,B.p1,B.p2) or point_on_segment(A.p2,B.p1,B.p2) or point_on_segment(B.p1,A.p1,A.p2) or point_on_segment(B.p2,A.p1,A.p2):
                        share=True
                if share: union2(i,j)
        comps2={}
        for i in range(len(la2)):
            comps2.setdefault(find2(i),[]).append(la2[i])
        singles_local=[]
        groups_local=[]
        for comp in comps2.values():
            if len(comp)==1:
                singles_local.append(comp[0])
            else:
                # sort within group by seq
                comp_sorted=sorted(comp, key=lambda p:p.seq)
                groups_local.append(comp_sorted)
        singles_local.extend(others)
        # sort singles by seq
        singles_local=sorted(singles_local, key=lambda p:p.seq)
        result_singles.extend(singles_local)
        # groups sorted by min seq
        groups_local=sorted(groups_local, key=lambda g: min(p.seq for p in g))
        result_groups.extend(groups_local)

    # text prim handling for non-ascii splitting: for now, if a text contains non-ascii and would split,
    # we keep original for ascii; for non-ascii, attempt replicate group splitting if multiple nodes needed.
    # Process text prims that are in result_singles: if any char ord>127, we may need to convert.
    # We'll handle during rendering: a text Prim may have .nodes list.
    def process_text_nodes(p):
        s=p.text
        if all(ord(ch)<128 for ch in s):
            return [p]  # single
        # If text contains wide chars (width 2) - use East Asian width
        # Determine if any char is wide/fullwidth
        # For now implement the observed byte-interleaving bug for 2-byte chars group:
        # If all non-ascii chars are 2-byte (len utf8==2) and there is at least one sequence of >=2 non-ascii (?)...
        # Simpler: if s contains a char with utf8 len==2 and the text, when split, original creates group in many cases.
        # Cases observed:
        # - single non-ascii at end or single in middle followed by ascii at end as single nodes? "eé" single, "aαb" group, "aaé" single.
        # Rule from earlier: nodes are formed by taking characters in steps? Let's implement algorithm discovered for group cases:
        # When a text Prim becomes a group, its nodes are generated by an unknown process; we attempt the following for 2-byte dominated strings:
        # If s has at least 2 non-ascii chars, create group nodes using interleaving by max_utf8_len:
        nonascii=[ch for ch in s if ord(ch)>127]
        if len(nonascii)>=2:
            # Compute step = max utf8 byte length among chars in s (capped?)
            step=max(len(ch.encode('utf-8')) for ch in s)
            if step==2:
                nodes=[]
                # nodes start at positions 0..? The number nodes = ?
                # Observed: for strings starting with nonascii, nodes start at char index 0 and 1; for "abγδ" nodes start 0 and 3? hmm.
                # Use a different observed model: build nodes by scanning and assigning each char to a node based on byte offset parity?
                # Model attempt: maintain byte_index for each char; node index = (byte_index % step) ??? Let's test vs data:
                # αβγδ: byte idx 0,2,4,6 -> mod2=0 for all, not.
                # Alternative: char index % step
                nodes_dict={}
                order=[]
                for idx,ch in enumerate(s):
                    k=idx % step
                    if k not in nodes_dict:
                        nodes_dict[k]=[]; order.append(k)
                    nodes_dict[k].append(ch)
                # But node start x should be the cell index of first char in that node
                # Determine first idx for each k
                nodes=[]
                for k in order:
                    first_idx=k  # since idx%step==k first occurrence is k (if k < len)
                    if first_idx>=len(s): continue
                    txt=''.join(nodes_dict[k])
                    np=Prim('text',cell=p.cell); np.x=( (p.x-2)//8 + first_idx)*8+2 if False else p.x + first_idx*8; np.y=p.y; np.text=txt; np.seq=p.seq; np.cluster=p.cluster
                    nodes.append(np)
                if len(nodes)>1:
                    p.nodes=nodes
                    return [p]
            elif step>=3:
                # for 3/4 byte, original often separates each nonascii as single elements, not group; leave as is for now (will be inaccurate)
                return [p]
        return [p]

    # Apply text processing: singles that are text and need nodes become groups
    new_singles=[]
    extra_groups=[]
    for p in result_singles:
        if p.kind=='text':
            process_text_nodes(p)
            if p.nodes:
                extra_groups.append(p.nodes if False else p)  # p itself will be rendered as group
                # mark as group holder: we will handle in rendering lists
                # move to groups list as a special Prim with nodes
                result_groups.append([p])  # placeholder, rendering special
                continue
        new_singles.append(p)
    result_singles=new_singles
    # Note: groups appended from text may be out of order vs line groups; original groups order: need sort groups by seq
    # result_groups contains lists and also [textPrim] specials; sort by min seq
    def group_seq(g):
        # g is list of prims, or [text prim with nodes]
        return min(x.seq for x in g)
    result_groups=sorted(result_groups, key=group_seq)

    # Rendering
    scale=settings.scale
    def S(v):
        return fmt_f32(f32(v)*scale) if False else fmt_f32(f32(f32(v)*scale))
    # Actually coordinates: v is unscaled (int/float). scaled = f32(v * scale) where v converted to f32 first?
    def SC(v):
        return fmt_f32(f32(f32(v)*scale))
    Wscaled=SC(total_w); Hscaled=SC(total_h)
    out=[]
    out.append(f'<svg xmlns="http://www.w3.org/2000/svg" width="{Wscaled}" height="{Hscaled}" class="svgbob">')
    style=STYLE_TMPL.format(stroke=settings.stroke_color, sw=fmt_f32(settings.stroke_width), ff=settings.font_family, fs=settings.font_size, bg=settings.background, fill=settings.fill_color)
    out.append('  <style>'+style+'</style>')
    out.append(DEFS.rstrip('\n'))
    out.append(f'  <rect class="backdrop" x="0" y="0" width="{Wscaled}" height="{Hscaled}"></rect>')
    def render_prim(p, indent):
        pre=' '*indent
        if p.kind=='line':
            return f'{pre}<line x1="{SC(p.p1[0])}" y1="{SC(p.p1[1])}" x2="{SC(p.p2[0])}" y2="{SC(p.p2[1])}" class="{p.cls}"></line>'
        if p.kind=='arc':
            return f'{pre}<path d="M {SC(p.p1[0])},{SC(p.p1[1])} A {SC(p.r)},{SC(p.r)} 0,{p.large},{p.sweep} {SC(p.p2[0])},{SC(p.p2[1])}" class="{p.cls}"></path>'
        if p.kind=='circle':
            return f'{pre}<circle cx="{SC(p.x)}" cy="{SC(p.y)}" r="{SC(p.r)}" class="{p.cls}"></circle>'
        if p.kind=='rect':
            return f'{pre}<rect x="{SC(p.x)}" y="{SC(p.y)}" width="{SC(p.w)}" height="{SC(p.h)}" class="{p.cls}" rx="{SC(p.rx)}"></rect>'
        if p.kind=='polygon':
            pts=' '.join(f"{SC(px)},{SC(py)}" for px,py in p.points)
            return f'{pre}<polygon points="{pts}" class="{p.cls}"></polygon>'
        if p.kind=='text':
            if indent==2:
                return f'{pre}<text x="{SC(p.x)}" y="{SC(p.y)}" >{xml_escape(p.text)}</text>'
            else:
                return f'{pre}<text x="{SC(p.x)}" y="{SC(p.y)}">{xml_escape(p.text)}</text>'
        return ''
    for p in result_singles:
        out.append(render_prim(p,2))
    for p in quoted_prims:
        out.append(render_prim(p,2))
    for g in result_groups:
        # g is a list of prims; if it's a text group placeholder [textPrim with nodes]
        if len(g)==1 and g[0].kind=='text' and g[0].nodes:
            out.append('  <g>')
            for np_ in g[0].nodes:
                out.append(render_prim(np_,4))
            out.append('  </g>')
        else:
            out.append('  <g>')
            for p in g:
                out.append(render_prim(p,4))
            out.append('  </g>')
    out.append('</svg>')
    return '\n'.join(out)+'\n'

