import subprocess, random, sys
from concurrent.futures import ProcessPoolExecutor
ORIG="/workspace/executable"; MINE="/tmp/mine/executable"
def one(txt):
    r1=subprocess.run([ORIG],input=txt.encode(),capture_output=True)
    r2=subprocess.run([MINE],input=txt.encode(),capture_output=True)
    if r1.stdout!=r2.stdout:
        def body(b):
            t=b.decode(errors='replace'); i=t.find("</defs>"); return t[i+8:] if i!=-1 else t
        return (txt, body(r1.stdout), body(r2.stdout))
    return None
def gen(n, seed):
    rng=random.Random(seed)
    chars="+-|/\\_~=<>^vvoO*#()'.,:;ab "
    out=[]
    for i in range(n):
        rows=rng.randint(1,4); cols=rng.randint(1,10)
        txt="\n".join("".join(rng.choice(chars) for _ in range(cols)) for _ in range(rows))
        out.append(txt)
    return out
if __name__=="__main__":
    n=int(sys.argv[1]); seed=int(sys.argv[2])
    tests=gen(n,seed)
    fails=[]
    with ProcessPoolExecutor(max_workers=8) as ex:
        for res in ex.map(one, tests):
            if res: fails.append(res)
    print(f"{n-len(fails)}/{n} passed, seed={seed}")
    for txt,a,b in fails[:15]:
        print("INPUT",repr(txt)); print(" orig",a[:1500]); print(" mine",b[:1500]); print("---")
