import sys; sys.path.insert(0,'/tmp')
from probe import *
import string
chars=[c for c in string.printable if c not in ' \t\n\r\x0b\x0c']
def cat_paren(txt, paren_row):
    # txt is 2 rows; determine paren output: find paths/text containing paren
    r=run([],inp=txt); b=body(r.stdout)
    if f'>{paren_row}<' in b or (paren_row=='(' and '>(<' in b): return 'T'
    # check paths
    import re
    paths=re.findall(r'd="([^"]+)"',b)
    if not paths: return 'T?'
    # normal vs modified
    for d in paths:
        if 'A 16,16' in d: return 'N'  # normal
        if 'A 12,12' in d: return 'M'  # modified
    return 'O'+str(paths)
for paren in ['(',')']:
    for direction in ['south','north']:
        cats={}
        for c in chars:
            txt=f"{paren}\n{c}" if direction=='south' else f"{c}\n{paren}"
            cats.setdefault(cat_paren(txt,paren),[]).append(c)
        print(paren,direction,cats)
