import subprocess
from concurrent.futures import ProcessPoolExecutor
ORIG="/workspace/executable"; MINE="/tmp/mine/executable"
chars="-|/\\+._~=<>^vvoO*#()'x: "
def one(txt):
    r1=subprocess.run([ORIG],input=txt.encode(),capture_output=True)
    r2=subprocess.run([MINE],input=txt.encode(),capture_output=True)
    return None if r1.stdout==r2.stdout else txt
for name,tests in [("hpairs",[a+b for a in chars for b in chars]),("vpairs",[a+"\n"+b for a in chars for b in chars])]:
    with ProcessPoolExecutor(max_workers=16) as ex:
        fails=[r for r in ex.map(one, tests) if r]
    print(name, f"{len(tests)-len(fails)}/{len(tests)}", fails[:60])
