import subprocess, random
ORIG="/workspace/executable"; MINE="/tmp/mine/executable"
def one(args):
    inp=b"--> test\n+---+\n|   |\n+---+"
    r1=subprocess.run([ORIG]+args,input=inp,capture_output=True)
    r2=subprocess.run([MINE]+args,input=inp,capture_output=True)
    return None if (r1.stdout==r2.stdout and r1.returncode==r2.returncode and r1.stderr==r2.stderr) else (args,r1.stdout[:300],r2.stdout[:300],r1.stderr[:200],r2.stderr[:200])
rng=random.Random(42)
cases=[]
for i in range(40):
    v=rng.choice(["0.1","0.5","1.5","2.75","0.333","3.14159","1e3","1e-3","123.456","0.0001","999","1e10","1e-10","5e-324","3.4028235e38","1.17549435e-38"])
    cases.append(["--scale",v,"-s","hi"])
    cases.append(["--stroke-width",v,"-s","hi"])
for v in ["0","1","14","100","1000","18446744073709551615"]:
    cases.append(["--font-size",v,"-s","hi"])
fails=[]
from concurrent.futures import ProcessPoolExecutor
with ProcessPoolExecutor(max_workers=8) as ex:
    for r in ex.map(one,cases):
        if r: fails.append(r)
print(f"{len(cases)-len(fails)}/{len(cases)} numeric passed")
for f in fails[:5]: print(f)
