import subprocess, random, sys
from concurrent.futures import ProcessPoolExecutor
ORIG="/workspace/executable"; MINE="/tmp/mine/executable"
def one(txt):
    r1=subprocess.run([ORIG],input=txt.encode(),capture_output=True)
    r2=subprocess.run([MINE],input=txt.encode(),capture_output=True)
    if r1.stdout!=r2.stdout:
        def body(b):
            t=b.decode(errors='replace'); i=t.find("</defs>"); return t[i+8:] if i!=-1 else t
        return (txt,body(r1.stdout),body(r2.stdout))
    return None
def gen(seed):
    rng=random.Random(seed); out=[]
    for i in range(60):
        # place a few boxes and arrows on canvas
        W=40; H=12
        grid=[[" "]*W for _ in range(H)]
        def box(x,y,w,h,label=None,rounded=False):
            tl,tr,bl,br=('+','+','+','+') if not rounded else ('.','.',"'","'")
            grid[y][x]=tl; grid[y][x+w-1]=tr; grid[y+h-1][x]=bl; grid[y+h-1][x+w-1]=br
            for xx in range(x+1,x+w-1): grid[y][xx]='-'; grid[y+h-1][xx]='-'
            for yy in range(y+1,y+h-1): grid[yy][x]='|'; grid[yy][x+w-1]='|'
            if label:
                for j,ch in enumerate(label[:w-2]):
                    if y+1<H and x+1+j<W: grid[y+1][x+1+j]=ch
        for _ in range(rng.randint(1,3)):
            box(rng.randint(0,20),rng.randint(0,7),rng.randint(5,12),3,label=rng.choice([None,"Hi","Foo","A B","x"]))
        txt="\n".join("".join(r).rstrip() for r in grid)
        out.append(txt)
    return out
if __name__=="__main__":
    tests=gen(7)
    fails=[]
    with ProcessPoolExecutor(max_workers=8) as ex:
        for r in ex.map(one,tests):
            if r: fails.append(r)
    print(f"{len(tests)-len(fails)}/{len(tests)} structured passed")
    for txt,a,b in fails[:4]:
        print("INPUT\n"+txt); print("orig",a[:1200]); print("mine",b[:1200]); print("---")
